    /// <summary>
    ///     JavaScript-Invokable Method for internal use only.
    /// </summary>
    [JSInvokable]
    public async Task OnJsEdits(IJSStreamReference jsStreamRef)
    {
        if (IsDisposed)
        {
            // cancel if the component is disposed
            return;
        }
    
        SceneLayerEditsEvent? editsEvent = await jsStreamRef.ReadJsStreamReference<SceneLayerEditsEvent>();
        if (editsEvent is not null)
        {
            await OnEdits.InvokeAsync(editsEvent);
        }
    }
    
    /// <summary>
    ///     <a target="_blank" href="https://docs.geoblazor.com/pages/classes/dymaptic.GeoBlazor.Pro.Components.Layers.SceneLayer.html#scenelayeronedits-property">GeoBlazor Docs</a>
    ///     Fires after <a href="#applyEdits">applyEdits()</a> is completed successfully.
    ///     The event payload includes only successful edits, not the failed edits.
    /// </summary>
    [Parameter]
    [JsonIgnore]
    public EventCallback<SceneLayerEditsEvent> OnEdits { get; set; }
   
    /// <summary>
    ///     Used in JavaScript layer to determine if the event listener is registered.
    /// </summary>
    public bool HasEditsListener => OnEdits.HasDelegate;
    
